/* B2 lessons · part 1 */
L({ id: "b2-subj", lvl: "B2", tr: "nuance", cat: "subjonctif", t: "Subjonctif après les conjonctions", en: "Bien que, pour que, avant que, à condition que, jusqu'à ce que",
  rule: { h: "Some conjunctions always take the subjunctive; après que, pendant que and parce que take the indicative.",
    pts: ["<b>Concession</b>: <i>bien que, quoique</i> — <i>bien qu'il soit tard, je continue</i>.", "<b>Purpose</b>: <i>pour que, afin que, de sorte que (purpose)</i> — <i>je parle lentement pour que tu comprennes</i>.", "<b>Time</b>: <i>avant que, jusqu'à ce que, en attendant que</i> — <i>reste jusqu'à ce qu'il revienne</i>.", "<b>Condition</b>: <i>à condition que, pourvu que, à moins que</i> — <i>je viendrai à condition que tu m'invites</i>.", "<b>Indicative</b> after <i>après que, pendant que, parce que, depuis que, alors que</i>."],
    ex: [["Bien qu'il pleuve, nous sortons.", "Although it is raining, we are going out."], ["Je t'explique pour que tu saches quoi faire.", "I'm explaining so that you know what to do."], ["Rentre avant qu'il fasse nuit.", "Come home before it gets dark."], ["Elle viendra à condition qu'on finisse tôt.", "She'll come on condition that we finish early."]],
    warn: "With the same subject, use a preposition + infinitive: <i>je travaille <b>pour</b> réussir</i>, <i>appelle-moi <b>avant de</b> partir</i>. Que + subjunctive is for two different subjects.",
    vn: "Tiếng Việt: <b>mặc dù, để, trước khi, miễn là, cho đến khi</b> không đổi động từ. Tiếng Pháp: bien que, pour que, avant que, à condition que, jusqu'à ce que + <b>subjonctif</b>. Nhưng <b>après que</b> (sau khi) + indicatif." },
  cards: [["bien que", "although", "Bien qu'elle soit fatiguée, elle sort.", "Although she's tired, she goes out."], ["pour que", "so that", "Je répète pour que tout le monde entende.", "I'm repeating so everyone can hear."], ["avant que", "before", "Partons avant qu'il pleuve.", "Let's go before it rains."], ["jusqu'à ce que", "until", "J'attendrai jusqu'à ce que tu reviennes.", "I'll wait until you come back."], ["à condition que", "on condition that", "D'accord, à condition que tu m'aides.", "OK, on condition that you help me."], ["à moins que", "unless", "Je viendrai, à moins qu'il y ait une grève.", "I'll come, unless there's a strike."], ["pourvu que", "let's hope that, provided that", "Pourvu qu'il fasse beau demain !", "Let's hope it's fine tomorrow!"], ["après que", "after (+ indicative)", "Après qu'il est parti, j'ai rangé.", "After he left, I tidied up."]],
  sent: [["Bien que le loyer soit élevé, nous restons dans ce quartier.", "Although the rent is high, we're staying in this area."], ["Je t'envoie le lien pour que tu puisses t'inscrire.", "I'm sending you the link so you can sign up."], ["Il faut finir le projet avant que le client revienne.", "We need to finish the project before the client comes back."], ["Nous attendrons jusqu'à ce que tout le monde soit arrivé.", "We'll wait until everyone has arrived."], ["Je veux bien présenter le module, à condition que tu fasses la démo.", "I'm happy to present the module, provided you do the demo."], ["On partira à huit heures, à moins qu'il fasse trop froid.", "We'll leave at eight, unless it's too cold."], ["Pourvu que le vol ne soit pas annulé !", "Let's hope the flight isn't cancelled!"], ["Elle a fini son master bien qu'elle travaille à plein temps.", "She finished her master's although she works full time."], ["Après que nous avons signé le bail, nous avons fêté ça.", "After we signed the lease, we celebrated."], ["J'explique les consignes en vietnamien afin que mes parents comprennent.", "I explain the instructions in Vietnamese so that my parents understand."]],
  nat: [["Bien qu'il soit malade, il travaille.", "Bien qu'il est malade, il travaille.", "Bien que + subjunctive."], ["Appelle-moi avant de partir.", "Appelle-moi avant que tu partes.", "Same subject (tu): avant de + infinitive."], ["Après qu'il est arrivé, nous avons dîné.", "Après qu'il soit arrivé, nous avons dîné.", "Après que + indicative in careful French (the subjunctive is common in speech but criticised)."], ["Je travaille pour que mes enfants aient une bonne vie.", "Je travaille pour que mes enfants ont une bonne vie.", "Pour que + subjunctive."]],
  mcq: [["Je t'attends jusqu'à ce que tu ___.", "reviennes", ["reviens", "reviendras", "revenais"], "Jusqu'à ce que + subjunctive."], ["___ il fasse froid, les enfants jouent dehors.", "Bien qu'", ["Parce qu'", "Puisqu'", "Malgré qu'"], "Concession + subjunctive: bien que."], ["Je fais ça ___ réussir.", "pour", ["pour que", "afin que", "bien que"], "Same subject → pour + infinitive."], ["Il est parti ___ je puisse lui dire au revoir.", "avant que", ["après que", "parce que", "pendant que"], "Avant que + subjunctive."]],
  gap: [["Bien qu'elle ___ peur de l'avion, elle part au Japon.", "ait", "avoir", "Although she's afraid of flying, she's going to Japan.", ["a", "aura", "avait"]], ["Je parle fort pour que tout le monde m'___.", "entende", "entendre", "I speak loudly so that everyone hears me.", ["entend", "entendra", "entendait"]], ["Fermez la porte avant que le chat ___.", "sorte", "sortir", "Close the door before the cat gets out.", ["sort", "sortira", "sortait"]], ["Je te prête ma voiture à condition que tu ___ prudent.", "sois", "être", "I'll lend you my car provided you're careful.", ["es", "seras", "étais"]], ["Restez ici jusqu'à ce que je vous ___.", "appelle", "appeler", "Stay here until I call you.", ["appellerai", "appelais", "appelez"]], ["Pourvu qu'ils ___ à l'heure !", "arrivent", "arriver", "Let's hope they arrive on time!", ["arriveront", "arrivaient", "arriveraient"]]],
  fix: [["Bien qu'il fait beau, je reste chez moi.", "fait", "fasse", "Bien que + subjunctive.", ["fera", "faisait"]], ["Je t'appelle avant que je parte.", "avant que je parte", "avant de partir", "Same subject → avant de + infinitive.", ["avant que je pars", "avant partir"]], ["Je l'aide pour qu'il réussit.", "réussit", "réussisse", "Pour que + subjunctive.", ["réussira", "réussissait"]]],
  xf: [["Join with bien que.", "Il est riche. Il n'est pas heureux.", "Bien qu'il soit riche, il n'est pas heureux."], ["Join with pour que.", "Je t'envoie le plan. Tu trouves la maison.", "Je t'envoie le plan pour que tu trouves la maison."]],
  chat: [["Tu viens au séminaire vendredi ?", "Oui, à condition que la réunion du matin finisse à temps.", ["Oui, à condition que la réunion finit à temps.", "Oui, à condition de la réunion finisse."], "À condition que + subjunctive."], ["On part maintenant ?", "Attendons jusqu'à ce que la pluie s'arrête.", ["Attendons jusqu'à ce que la pluie s'arrêtera.", "Attendons jusqu'à la pluie s'arrête."], "Jusqu'à ce que + subjunctive."]]
});

L({ id: "b2-condpasse", lvl: "B2", tr: "temps2", cat: "hypothese", t: "Le conditionnel passé", en: "Regrets, reproaches and si + plus-que-parfait",
  rule: { h: "Si + plus-que-parfait → conditionnel passé: an imaginary past that did not happen.",
    pts: ["Form: <i>avoir / être</i> in the conditional + past participle: <i>j'aurais aimé, elle serait venue</i>.", "<b>Unreal past</b>: <i>si j'avais su, je serais venue</i> (but I didn't know, so I didn't come).", "<b>Regret</b>: <i>j'aurais dû t'écouter, j'aurais aimé être là</i>.", "<b>Reproach</b>: <i>tu aurais pu me prévenir !</i>", "<b>Mixed</b>: past condition, present result: <i>si j'avais pris ce poste, je vivrais à Lyon aujourd'hui</i>."],
    ex: [["Si nous étions partis plus tôt, nous n'aurions pas raté l'avion.", "If we had left earlier, we wouldn't have missed the plane."], ["J'aurais dû réserver plus tôt.", "I should have booked earlier."], ["Tu aurais pu m'appeler !", "You could have called me!"], ["Si j'avais appris le français enfant, je le parlerais sans accent.", "If I had learnt French as a child, I'd speak it without an accent."]],
    warn: "Never <i>si j'aurais su</i>: after si, the plus-que-parfait (<i>si j'avais su</i>).",
    vn: "<b>«Giá mà… thì đã…»</b>, <b>«lẽ ra… »</b>: <i>j'aurais dû</i> = lẽ ra tôi phải; <i>tu aurais pu</i> = lẽ ra bạn đã có thể; <i>si j'avais su, je serais venue</i> = giá mà biết thì tôi đã đến." },
  cards: [["j'aurais dû", "I should have", "J'aurais dû prendre un parapluie.", "I should have taken an umbrella."], ["tu aurais pu", "you could have", "Tu aurais pu me le dire !", "You could have told me!"], ["j'aurais aimé", "I would have liked", "J'aurais aimé rencontrer ton grand-père.", "I would have liked to meet your grandfather."], ["si j'avais su", "if I had known", "Si j'avais su, je ne serais pas venue.", "If I had known, I wouldn't have come."], ["regretter de", "to regret", "Je regrette de ne pas avoir appelé.", "I regret not calling."], ["un reproche", "a reproach", "Ce n'est pas un reproche, mais…", "It's not a criticism, but…"], ["à ta place, j'aurais…", "if I'd been you, I'd have…", "À ta place, j'aurais refusé.", "If I'd been you, I'd have refused."], ["sans toi", "without you", "Sans toi, je n'aurais jamais réussi.", "Without you, I'd never have succeeded."]],
  sent: [["Si j'avais su que tu étais à Paris, je t'aurais appelée.", "If I'd known you were in Paris, I'd have called you."], ["Nous aurions dû partir plus tôt.", "We should have left earlier."], ["Tu aurais pu me prévenir que tu serais en retard.", "You could have warned me you'd be late."], ["Elle serait venue si elle n'avait pas été malade.", "She would have come if she hadn't been ill."], ["J'aurais aimé que ma grand-mère voie notre mariage.", "I would have liked my grandmother to see our wedding."], ["Sans ton aide, je n'aurais jamais trouvé cet appartement.", "Without your help, I'd never have found this flat."], ["Si nous avions réservé, nous aurions eu une table.", "If we had booked, we'd have had a table."], ["À ta place, j'aurais demandé une augmentation.", "In your place, I would have asked for a raise."], ["Si tu avais pris le métro, tu serais déjà arrivée.", "If you'd taken the metro, you'd already be there."], ["Si j'avais accepté ce poste, je vivrais à Genève maintenant.", "If I'd accepted that job, I'd be living in Geneva now."]],
  nat: [["Si j'avais su, je serais venue.", "Si j'aurais su, je serais venue.", "After si: plus-que-parfait."], ["J'aurais dû t'écouter.", "J'aurais dû écouter toi.", "Pronoun before the infinitive."], ["Il serait venu s'il avait pu.", "Il aurait venu s'il avait pu.", "Venir takes être."], ["Si tu avais travaillé, tu aurais réussi.", "Si tu avais travaillé, tu réussiras.", "Unreal past → conditionnel passé."]],
  mcq: [["Si nous ___ le temps, nous serions passés te voir.", "avions eu", ["aurions eu", "avons eu", "aurons eu"], "Si + plus-que-parfait."], ["Tu ___ me demander avant de prendre ma voiture !", "aurais dû", ["devrais eu", "as dû", "devras"], "A reproach about the past: conditionnel passé of devoir."], ["Si elle avait pris le train, elle ___ à l'heure.", "serait arrivée", ["aurait arrivé", "arriverait été", "sera arrivée"], "Arriver → être; agreement with elle."], ["Si j'avais étudié le droit, je ___ avocate aujourd'hui.", "serais", ["aurais été", "serai", "étais"], "Mixed: past condition, present result → conditionnel présent."]],
  gap: [["Si tu m'avais demandé, je t'___ aidée.", "aurais", "avoir", "If you had asked me, I'd have helped you.", ["avais", "aurai", "aies"]], ["J'aurais ___ venir, mais j'étais malade.", "aimé", "aimer", "I would have liked to come, but I was ill.", ["aimer", "aimais", "aimée"]], ["Si nous ___ partis à l'heure, nous aurions eu le train.", "étions", "être", "If we'd left on time, we'd have caught the train.", ["serions", "avions", "sommes"]], ["Vous ___ dû réserver plus tôt.", "auriez", "avoir", "You should have booked earlier.", ["aurez", "aviez", "seriez"]], ["Sans ton message, je n'___ jamais su.", "aurais", "avoir", "Without your message, I'd never have known.", ["avais", "aurai", "ai"]], ["Elle ___ restée plus longtemps si elle avait pu.", "serait", "être", "She'd have stayed longer if she could have.", ["aurait", "sera", "était"]]],
  fix: [["Si j'aurais eu le temps, je serais venue.", "j'aurais eu", "j'avais eu", "After si: plus-que-parfait.", ["j'aurai eu", "j'ai eu"]], ["Il aurait venu avec nous.", "aurait venu", "serait venu", "Venir takes être.", ["aurait venue", "sera venu"]], ["Tu aurais pu me le dis.", "dis", "dire", "After pouvoir: infinitive.", ["dit", "disais"]]],
  xf: [["Express it as a regret with j'aurais dû.", "Je n'ai pas révisé.", "J'aurais dû réviser."], ["Make it an unreal past.", "Il pleut, donc je ne sors pas. (yesterday)", "S'il n'avait pas plu, je serais sortie.|S'il n'avait pas plu, je serais sorti."]],
  chat: [["J'ai raté l'entretien, j'étais trop stressée.", "Tu aurais dû me le dire, on se serait entraînées ensemble.", ["Tu devais me le dire, on s'entraînera.", "Tu aurais dû me le dis."], "Reproach and unreal past: conditionnel passé."], ["Tu regrettes d'être venue en France ?", "Non ! Si j'étais restée au Viêt Nam, je n'aurais pas rencontré Alex.", ["Si je serais restée au Viêt Nam…", "Si je restais au Viêt Nam, je ne rencontre pas Alex."], "Si + plus-que-parfait, then conditionnel passé."]]
});

L({ id: "b2-concordance", lvl: "B2", tr: "temps2", cat: "discours", t: "La concordance des temps", en: "Reported speech in the past",
  rule: { h: "When the reporting verb is in the past, the reported verbs move one step back.",
    pts: ["Présent → <b>imparfait</b>: <i>« Je suis fatiguée » → elle a dit qu'elle était fatiguée</i>.", "Passé composé → <b>plus-que-parfait</b>: <i>« J'ai fini » → il a dit qu'il avait fini</i>.", "Futur → <b>conditionnel présent</b>: <i>« Je viendrai » → elle a dit qu'elle viendrait</i>.", "Futur proche → <i>allait</i> + infinitive.", "Time words change: <i>aujourd'hui → ce jour-là, demain → le lendemain, hier → la veille, la semaine prochaine → la semaine suivante</i>."],
    ex: [["Elle m'a dit qu'elle habitait à Lyon.", "She told me she lived in Lyon."], ["Il a expliqué qu'il avait raté son train.", "He explained he had missed his train."], ["Ils ont promis qu'ils viendraient le lendemain.", "They promised they'd come the next day."], ["Je lui ai demandé s'il allait accepter.", "I asked him if he was going to accept."]],
    warn: "Imparfait, plus-que-parfait and conditional do not change: <i>« J'étais malade » → elle a dit qu'elle était malade</i>.",
    vn: "Tiếng Việt không đổi thì khi thuật lại (Cô ấy nói cô ấy <b>mệt</b>). Tiếng Pháp phải <b>lùi thì</b> khi động từ dẫn ở quá khứ: est → était, a fini → avait fini, viendra → viendrait." },
  cards: [["le lendemain", "the next day", "Il a dit qu'il partirait le lendemain.", "He said he'd leave the next day."], ["la veille", "the day before", "Elle a dit qu'elle était arrivée la veille.", "She said she had arrived the day before."], ["ce jour-là", "that day", "Il a dit qu'il était occupé ce jour-là.", "He said he was busy that day."], ["promettre que", "to promise that", "Il a promis qu'il rappellerait.", "He promised he would call back."], ["affirmer que", "to claim, to state that", "Elle a affirmé qu'elle n'avait rien vu.", "She stated she had seen nothing."], ["annoncer que", "to announce that", "Ils ont annoncé qu'ils se mariaient.", "They announced they were getting married."], ["avouer que", "to admit that", "Il a avoué qu'il avait oublié.", "He admitted he had forgotten."], ["la semaine suivante", "the following week", "Elle a dit qu'elle reviendrait la semaine suivante.", "She said she'd come back the following week."]],
  sent: [["Ma mère m'a dit qu'elle était fière de moi.", "My mother told me she was proud of me."], ["Le directeur a annoncé que l'entreprise allait recruter.", "The director announced the company was going to hire."], ["Elle a expliqué qu'elle avait perdu son badge.", "She explained she had lost her badge."], ["Ils nous ont promis qu'ils viendraient au mariage.", "They promised us they would come to the wedding."], ["Je lui ai demandé où elle avait acheté sa robe.", "I asked her where she had bought her dress."], ["Il a affirmé qu'il n'avait jamais reçu le colis.", "He claimed he had never received the parcel."], ["Le médecin m'a dit que je devais me reposer.", "The doctor told me I had to rest."], ["Alex a dit qu'il rentrerait le lendemain.", "Alex said he'd come home the next day."], ["Elle voulait savoir si nous avions déjà visité Hội An.", "She wanted to know if we had already visited Hội An."], ["Le guide a précisé que le musée fermait à dix-huit heures.", "The guide specified that the museum closed at six."]],
  nat: [["Il a dit qu'il était malade.", "Il a dit qu'il est malade hier.", "Past reporting verb → imparfait."], ["Elle a dit qu'elle viendrait.", "Elle a dit qu'elle viendra.", "Futur → conditionnel."], ["Il a avoué qu'il avait menti.", "Il a avoué qu'il a menti.", "Passé composé → plus-que-parfait."], ["Elle m'a dit qu'elle partait le lendemain.", "Elle m'a dit qu'elle partait demain.", "In a past story, demain → le lendemain."]],
  mcq: [["« Je suis contente. » → Elle a dit qu'elle ___ contente.", "était", ["est", "sera", "soit"], "Présent → imparfait."], ["« Nous partirons à six heures. » → Ils ont dit qu'ils ___ à six heures.", "partiraient", ["partiront", "partaient", "sont partis"], "Futur → conditionnel."], ["« J'ai trouvé un appartement. » → Il a annoncé qu'il ___ un appartement.", "avait trouvé", ["a trouvé", "trouvait", "trouverait"], "Passé composé → plus-que-parfait."], ["« Je pars demain. » → Elle a dit qu'elle partait ___.", "le lendemain", ["demain", "la veille", "hier"], "Demain → le lendemain."]],
  gap: [["« J'ai faim. » → Il a dit qu'il ___ faim.", "avait", "avoir", "He said he was hungry.", ["a", "aura", "aurait eu"]], ["« Je t'appellerai. » → Elle a promis qu'elle m'___.", "appellerait", "appeler", "She promised she would call me.", ["appellera", "appelait", "a appelé"]], ["« Nous avons visité Lyon. » → Ils ont dit qu'ils ___ Lyon.", "avaient visité", "visiter", "They said they had visited Lyon.", ["ont visité", "visitaient", "visiteraient"]], ["« Tu es libre ? » → Il m'a demandé si j'___ libre.", "étais", "être", "He asked me if I was free.", ["suis", "serai", "sois"]], ["« Je vais démissionner. » → Elle a dit qu'elle ___ démissionner.", "allait", "aller", "She said she was going to resign.", ["va", "ira", "irait"]], ["« Je suis arrivé hier. » → Il a dit qu'il était arrivé ___.", "la veille", "", "He said he had arrived the day before.", ["hier", "le lendemain", "demain"]]],
  fix: [["Elle m'a dit qu'elle viendra demain.", "viendra demain", "viendrait le lendemain", "Futur → conditionnel; demain → le lendemain.", ["viendrait demain", "vient le lendemain"]], ["Il a expliqué qu'il a perdu ses clés.", "a perdu", "avait perdu", "Passé composé → plus-que-parfait.", ["perdait", "perdra"]], ["Je lui ai demandé s'il est content.", "est", "était", "Présent → imparfait.", ["sera", "soit"]]],
  xf: [["Report in the past: Elle a dit que…", "« Je travaille à la maison aujourd'hui. »", "Elle a dit qu'elle travaillait à la maison ce jour-là."], ["Report in the past: Il a promis que…", "« Je finirai le rapport demain. »", "Il a promis qu'il finirait le rapport le lendemain."]],
  chat: [["Qu'est-ce que le propriétaire t'a dit ?", "Il m'a dit qu'il réparerait le chauffage la semaine suivante.", ["Il m'a dit qu'il réparera le chauffage la semaine prochaine.", "Il m'a dit qu'il répare le chauffage."], "Futur → conditionnel."], ["Et ta collègue, pourquoi elle est partie ?", "Elle a expliqué qu'elle avait trouvé un poste à Bordeaux.", ["Elle a expliqué qu'elle a trouvé un poste.", "Elle a expliqué qu'elle trouvera un poste."], "Passé composé → plus-que-parfait."]]
});

L({ id: "b2-futant", lvl: "B2", tr: "temps2", cat: "temps", t: "Le futur antérieur", en: "What will have happened before another future action",
  rule: { h: "The futur antérieur (avoir / être in the future + participle) marks an action completed before another future moment.",
    pts: ["Form: <i>j'aurai fini, elle sera partie, nous nous serons installés</i>.", "After <b>quand, dès que, lorsque, une fois que, après que</b>, when the action will be complete: <i>quand j'aurai fini, je t'appellerai</i>.", "Alone, with a time limit: <i>dans un an, j'aurai obtenu mon DALF</i>.", "To guess about the past: <i>il n'est pas là ? Il aura oublié</i> (he must have forgotten)."],
    ex: [["Quand tu auras lu ce livre, prête-le-moi.", "When you've read this book, lend it to me."], ["Dès que nous serons arrivés, nous t'enverrons un message.", "As soon as we've arrived, we'll send you a message."], ["D'ici juin, j'aurai terminé ma formation.", "By June, I'll have finished my training."], ["Il est en retard ; il aura raté son train.", "He's late; he must have missed his train."]],
    warn: "English uses the present perfect after <i>when</i> (<i>when I have finished</i>). French needs the futur antérieur: <i>quand j'aurai fini</i>.",
    vn: "Giống <b>«khi nào… xong thì…»</b>: <i>quand j'aurai fini</i> = khi nào tôi làm xong. Tiếng Việt chỉ thêm <b>xong, rồi</b>; tiếng Pháp cần một thì riêng." },
  cards: [["une fois que", "once", "Une fois que tu auras signé, c'est définitif.", "Once you've signed, it's final."], ["d'ici", "by (a deadline)", "D'ici ce soir, j'aurai fini.", "By tonight, I'll have finished."], ["dès que", "as soon as", "Dès qu'il sera rentré, on mangera.", "As soon as he's back, we'll eat."], ["terminer", "to finish", "Quand j'aurai terminé, je t'aiderai.", "When I've finished, I'll help you."], ["obtenir", "to obtain, to get", "D'ici un an, elle aura obtenu son diplôme.", "In a year's time she'll have got her diploma."], ["s'installer", "to settle in", "Quand nous nous serons installés, venez dîner.", "When we've settled in, come for dinner."], ["avoir oublié", "to have forgotten", "Il ne répond pas, il aura oublié son téléphone.", "He isn't answering, he must have forgotten his phone."], ["à la fin de", "at the end of", "À la fin de l'année, j'aurai lu vingt livres.", "By the end of the year, I'll have read twenty books."]],
  sent: [["Quand tu auras fini ton café, on y va.", "When you've finished your coffee, we'll go."], ["Dès que j'aurai reçu les résultats, je te préviendrai.", "As soon as I've got the results, I'll let you know."], ["D'ici décembre, nous aurons trouvé une salle pour la réception.", "By December, we'll have found a venue for the reception."], ["Une fois que vous aurez rempli le formulaire, envoyez-le.", "Once you've filled in the form, send it."], ["Lorsque les invités seront partis, nous rangerons.", "When the guests have left, we'll tidy up."], ["Dans deux ans, j'aurai passé le DALF C1.", "In two years, I'll have passed the DALF C1."], ["Elle n'est pas venue ; elle se sera trompée de jour.", "She didn't come; she must have got the day wrong."], ["Quand nous aurons visité le Louvre, nous irons au jardin des Tuileries.", "When we've visited the Louvre, we'll go to the Tuileries garden."], ["Après que tu auras parlé au directeur, appelle-moi.", "After you've spoken to the director, call me."], ["À la fin du stage, ils auront appris beaucoup de choses.", "By the end of the internship, they'll have learnt a lot."]],
  nat: [["Quand j'aurai fini, je sortirai.", "Quand j'ai fini, je sortirai.", "Completed before another future action: futur antérieur."], ["Dès qu'elle sera arrivée, on commencera.", "Dès qu'elle aura arrivé, on commencera.", "Arriver takes être."], ["D'ici lundi, j'aurai lu le rapport.", "D'ici lundi, j'ai lu le rapport.", "A deadline in the future: futur antérieur."], ["Une fois que nous aurons signé, nous fêterons ça.", "Une fois que nous signerons, nous avons fêté ça.", "Futur antérieur, then futur."]],
  mcq: [["Quand tu ___ tes devoirs, tu pourras jouer.", "auras fait", ["as fait", "feras", "aurais fait"], "Completed before the future action."], ["Dès que nous ___, nous vous écrirons.", "serons arrivés", ["aurons arrivé", "arrivons", "sommes arrivés"], "Arriver → être."], ["D'ici la fin du mois, j'___ tous mes cartons.", "aurai défait", ["ai défait", "aurais défait", "défaisais"], "A future deadline."], ["Il ne répond pas ? Il ___ son téléphone au bureau.", "aura laissé", ["laissera", "a laisser", "laissait"], "A guess about the past."]],
  gap: [["Quand j'___ terminé ce chapitre, j'irai me coucher.", "aurai", "avoir", "When I've finished this chapter, I'll go to bed.", ["ai", "aurais", "avais"]], ["Dès qu'elle ___ rentrée, nous dînerons.", "sera", "être", "As soon as she's home, we'll have dinner.", ["aura", "est", "serait"]], ["D'ici l'été, ils ___ trouvé un appartement.", "auront", "avoir", "By the summer, they'll have found a flat.", ["ont", "auraient", "avaient"]], ["Une fois que vous ___ payé, vous recevrez un reçu.", "aurez", "avoir", "Once you've paid, you'll receive a receipt.", ["avez", "auriez", "aviez"]], ["Lorsque nous nous ___ mariés, nous partirons en voyage.", "serons", "être", "When we've got married, we'll go travelling.", ["aurons", "sommes", "serions"]], ["Elle est en retard ; elle ___ raté le bus.", "aura", "avoir", "She's late; she must have missed the bus.", ["a", "aurait", "avait"]]],
  fix: [["Quand j'ai fini, je t'appellerai.", "j'ai fini", "j'aurai fini", "Completed before a future action: futur antérieur.", ["je finis", "j'aurais fini"]], ["Dès qu'il aura arrivé, on part.", "aura arrivé", "sera arrivé", "Arriver takes être.", ["est arrivé", "aurait arrivé"]], ["D'ici vendredi, j'aurai finir.", "finir", "fini", "Compound tenses use the participle.", ["finis", "finirai"]]],
  xf: [["Join with quand, using the futur antérieur.", "Je finis ma formation. Puis je chercherai un poste.", "Quand j'aurai fini ma formation, je chercherai un poste.|Quand j'aurai terminé ma formation, je chercherai un poste."], ["Use d'ici + futur antérieur.", "Je lis ce livre avant dimanche.", "D'ici dimanche, j'aurai lu ce livre."]],
  chat: [["On peut se voir après ton examen ?", "Oui, dès que j'aurai terminé, je t'enverrai un message.", ["Oui, dès que j'ai terminé, je t'envoie.", "Oui, dès que je terminerai, je t'ai envoyé."], "Completed before another future action."], ["Où est Alex ? Il devait être là à midi.", "Il aura oublié l'heure, comme d'habitude !", ["Il oubliait l'heure.", "Il oubliera l'heure demain."], "A guess about the past: futur antérieur."]]
});

L({ id: "b2-relcomp", lvl: "B2", tr: "phrase2", cat: "relatifs", t: "Lequel, auquel, duquel", en: "Compound relative pronouns after prepositions",
  rule: { h: "After a preposition, use lequel (agreeing with the noun); for people you can also use qui.",
    pts: ["<i>lequel, laquelle, lesquels, lesquelles</i> after <i>avec, pour, sans, dans, sur, par, parmi, entre</i>: <i>l'ordinateur avec lequel je travaille</i>.", "With <b>à</b>: <i>auquel, à laquelle, auxquels, auxquelles</i>: <i>le projet auquel je pense</i>.", "With <b>de</b> inside a phrase (<i>près de, à côté de, au cours de</i>): <i>duquel, de laquelle, desquels, desquelles</i>: <i>le parc près duquel j'habite</i>.", "For a person: <i>qui</i> is usual: <i>la collègue avec qui je travaille, l'ami à qui j'ai écrit</i>.", "Simple <b>de</b> (parler de, avoir besoin de): use <b>dont</b>, not duquel."],
    ex: [["Voici la raison pour laquelle je suis venue.", "Here is the reason why I came."], ["C'est un sujet auquel je réfléchis souvent.", "It's a subject I often think about."], ["La personne à qui j'ai parlé était très aimable.", "The person I spoke to was very kind."], ["L'immeuble en face duquel nous habitons est en travaux.", "The building opposite which we live is being renovated."]],
    warn: "Never <i>à lequel</i> or <i>de lequel</i>: contract them to <i>auquel, duquel</i> (and <i>auxquels, desquels</i>). <i>À laquelle, de laquelle</i> stay separate.",
    vn: "Tiếng Việt chỉ cần <b>mà</b> (cái máy <b>mà</b> tôi làm việc <b>với</b>). Tiếng Pháp đặt giới từ lên trước: <i>l'ordinateur <b>avec lequel</b> je travaille</i>, và lequel phải hợp giống, số với danh từ." },
  cards: [["avec lequel", "with which", "Le stylo avec lequel j'écris est neuf.", "The pen I'm writing with is new."], ["pour laquelle", "for which", "C'est la raison pour laquelle je pars.", "That's the reason why I'm leaving."], ["auquel", "to which (masc.)", "Le concours auquel j'ai participé était difficile.", "The competition I took part in was hard."], ["à laquelle", "to which (fem.)", "La conférence à laquelle j'assiste commence à 9 h.", "The conference I'm attending starts at 9."], ["duquel", "of which (masc.)", "Le jardin au milieu duquel il y a une fontaine…", "The garden in the middle of which there's a fountain…"], ["parmi lesquels", "among whom / which", "Des invités, parmi lesquels le maire.", "Guests, among them the mayor."], ["sans lequel", "without which", "Le badge sans lequel on ne peut pas entrer.", "The badge without which you can't get in."], ["grâce auquel", "thanks to which", "Le programme grâce auquel j'ai trouvé un emploi.", "The programme thanks to which I found a job."]],
  sent: [["Voilà l'outil avec lequel nous créons nos modules en ligne.", "Here's the tool we create our online modules with."], ["C'est la raison pour laquelle j'ai choisi ce master.", "That's why I chose this master's."], ["Le projet auquel je travaille sera lancé en mars.", "The project I'm working on will be launched in March."], ["La réunion à laquelle tu m'as invitée a été annulée.", "The meeting you invited me to was cancelled."], ["Les amis avec qui nous partons en vacances sont adorables.", "The friends we're going on holiday with are lovely."], ["C'est un problème auquel personne n'avait pensé.", "It's a problem nobody had thought of."], ["La table sur laquelle j'ai posé mes clés est dans l'entrée.", "The table I put my keys on is in the hall."], ["Le pont sous lequel passent les bateaux date du XVIIe siècle.", "The bridge under which the boats pass dates from the 17th century."], ["Plusieurs pays, parmi lesquels le Viêt Nam, ont signé l'accord.", "Several countries, including Vietnam, signed the agreement."], ["Le restaurant près duquel nous habitons est toujours plein.", "The restaurant near which we live is always full."]],
  nat: [["Le sujet auquel je pense est délicat.", "Le sujet à lequel je pense est délicat.", "À + lequel → auquel."], ["La raison pour laquelle je pars est simple.", "La raison pour lequel je pars est simple.", "Raison is feminine → laquelle."], ["Le livre dont je parle est épuisé.", "Le livre duquel je parle est épuisé.", "Simple de (parler de) → dont."], ["La collègue avec qui je travaille est italienne.", "La collègue avec que je travaille est italienne.", "After a preposition, never que: qui or laquelle."]],
  mcq: [["L'association ___ je participe aide les étudiants étrangers.", "à laquelle", ["auquel", "laquelle", "dont"], "Participer à + association (fem.) → à laquelle."], ["Ce sont des questions ___ je n'ai pas de réponse.", "auxquelles", ["auxquels", "dont", "lesquelles"], "Répondre / avoir une réponse à + questions (fem. pl.)."], ["Le collègue ___ j'ai prêté mon ordinateur est parti.", "à qui", ["que", "dont", "lequel"], "Prêter à + person → à qui (or auquel)."], ["Le bâtiment à côté ___ se trouve la gare est un musée.", "duquel", ["dont", "de lequel", "auquel"], "À côté de + bâtiment (masc.) → duquel."]],
  gap: [["Voici l'application avec ___ j'apprends le français.", "laquelle", "", "Here's the app I learn French with.", ["lequel", "qui", "que"]], ["C'est un détail ___ je n'avais pas fait attention.", "auquel", "", "It's a detail I hadn't paid attention to.", ["à lequel", "dont", "lequel"]], ["Les raisons pour ___ il est parti restent floues.", "lesquelles", "", "The reasons why he left remain unclear.", ["lesquels", "laquelle", "qui"]], ["La personne à ___ j'ai envoyé le dossier ne répond pas.", "qui|laquelle", "", "The person I sent the file to isn't answering.", ["que", "dont", "lequel"]], ["Le parc au milieu ___ se trouve le lac est magnifique.", "duquel", "", "The park in the middle of which there's a lake is magnificent.", ["dont", "auquel", "de lequel"]], ["Ce sont des conditions sans ___ nous ne signerons pas.", "lesquelles", "", "These are conditions without which we won't sign.", ["lesquels", "quoi", "qui"]]],
  fix: [["C'est le projet à lequel je pense.", "à lequel", "auquel", "À + lequel → auquel.", ["duquel", "dont"]], ["La raison pour lequel je t'appelle est simple.", "lequel", "laquelle", "Raison is feminine.", ["lesquels", "quoi"]], ["La femme avec que je travaille est sympa.", "que", "qui", "After a preposition, use qui for a person.", ["dont", "lequel"]]],
  xf: [["Join with a compound relative pronoun.", "Je travaille sur un projet. Ce projet est passionnant.", "Le projet sur lequel je travaille est passionnant."], ["Join with a compound relative pronoun.", "J'ai assisté à une conférence. La conférence était en anglais.", "La conférence à laquelle j'ai assisté était en anglais."]],
  chat: [["Pourquoi tu as quitté ton ancien poste ?", "La raison pour laquelle je suis partie, c'est le manque de perspectives.", ["La raison pour lequel je suis partie…", "La raison que je suis partie…"], "Raison (fem.) → pour laquelle."], ["C'est quoi, ce logiciel ?", "C'est l'outil avec lequel on conçoit nos formations en ligne.", ["C'est l'outil avec que on conçoit…", "C'est l'outil dont on conçoit avec."], "After avec: lequel."]]
});

L({ id: "b2-passif", lvl: "B2", tr: "phrase2", cat: "syntaxe", t: "La voix passive", en: "Passive voice and its alternatives",
  rule: { h: "Passive = être (in the tense of the active verb) + past participle agreeing with the subject; the agent is introduced by par.",
    pts: ["<i>Le directeur a signé le contrat → le contrat <b>a été signé</b> par le directeur</i>.", "The participle agrees with the subject: <i>la loi a été votée, les décisions seront prises</i>.", "<b>De</b> instead of par with verbs of feeling or description: <i>il est aimé de tous, la ville est entourée de montagnes</i>.", "French uses the passive less than English. Alternatives: <b>on</b> (<i>on m'a volé mon vélo</i>) and the <b>pronominal</b> form (<i>ce plat se mange froid, ça ne se fait pas</i>).", "Only verbs with a direct object can be passive: you cannot say <i>j'ai été demandé de…</i> → <i>on m'a demandé de…</i>."],
    ex: [["Le musée a été construit au XIXe siècle.", "The museum was built in the 19th century."], ["Les candidats seront informés par e-mail.", "Candidates will be informed by email."], ["On m'a offert un poste à Lyon.", "I was offered a job in Lyon."], ["Le vin blanc se boit frais.", "White wine is drunk chilled."]],
    warn: "English <i>I was told</i>, <i>I was given</i>, <i>I was asked</i> cannot be passive in French: <i>on m'a dit, on m'a donné, on m'a demandé</i>.",
    vn: "Tiếng Việt dùng <b>bị</b> (xấu) hoặc <b>được</b> (tốt). Tiếng Pháp chỉ có một cấu trúc trung tính: <b>être + participe</b>. Nhưng người Pháp hay dùng <b>on</b> hơn: <i>On m'a volé mon vélo</i> = Tôi bị mất cắp xe đạp." },
  cards: [["être construit", "to be built", "Ce pont a été construit en 1900.", "This bridge was built in 1900."], ["par", "by (agent)", "Le livre a été traduit par une poétesse.", "The book was translated by a poet."], ["être aimé de", "to be loved by", "Ce professeur est aimé de ses élèves.", "This teacher is loved by his students."], ["être entouré de", "to be surrounded by", "Le village est entouré de rizières.", "The village is surrounded by rice fields."], ["on m'a dit", "I was told", "On m'a dit que c'était fermé.", "I was told it was closed."], ["se vendre", "to sell, to be sold", "Ce livre se vend très bien.", "This book is selling very well."], ["ça ne se fait pas", "it's not done", "Arriver les mains vides, ça ne se fait pas.", "Arriving empty-handed is not done."], ["être prévu", "to be planned", "La réunion est prévue à 10 h.", "The meeting is scheduled for 10."]],
  sent: [["Le contrat a été signé hier soir.", "The contract was signed last night."], ["Les résultats seront publiés en juillet.", "The results will be published in July."], ["Cette formation a été conçue par notre équipe.", "This training course was designed by our team."], ["La cathédrale est visitée par des millions de touristes.", "The cathedral is visited by millions of tourists."], ["On m'a demandé de présenter le projet.", "I was asked to present the project."], ["Le phở se mange avec des baguettes et une cuillère.", "Phở is eaten with chopsticks and a spoon."], ["La décision n'a pas encore été prise.", "The decision has not yet been taken."], ["Ma grand-mère était respectée de tout le village.", "My grandmother was respected by the whole village."], ["Les invitations ont été envoyées la semaine dernière.", "The invitations were sent last week."], ["Le français se parle sur cinq continents.", "French is spoken on five continents."]],
  nat: [["On m'a donné un badge.", "J'ai été donné un badge.", "Donner à quelqu'un is indirect: use on."], ["La loi a été votée en 2023.", "La loi a été voté en 2023.", "Agreement with the subject: votée."], ["Il est aimé de tous.", "Il est aimé par tous.", "With feelings, de is preferred."], ["Ce plat se mange chaud.", "Ce plat est mangé chaud normalement par on.", "General rule: pronominal passive."]],
  mcq: [["Les travaux ___ l'année prochaine.", "seront terminés", ["seront terminé", "auront terminés", "terminera"], "Future passive, agreement with travaux."], ["___ que la réunion était annulée.", "On m'a dit", ["J'ai été dit", "Je suis dit", "Il m'a été dit par on"], "Dire à quelqu'un → on m'a dit."], ["La maison est entourée ___ un grand jardin.", "d'", ["par", "avec", "à"], "Description: entouré de."], ["Ce mot ne ___ plus aujourd'hui.", "s'emploie", ["est employé par on", "emploie", "s'est employé hier"], "A general habit: pronominal form."]],
  gap: [["Le rapport a été ___ par la directrice.", "validé", "valider", "The report was approved by the director.", ["validée", "valider", "validés"]], ["Les décisions ___ prises demain.", "seront", "être", "The decisions will be taken tomorrow.", ["auront", "sont été", "serons"]], ["Cette chanson est connue ___ tout le monde.", "de", "", "This song is known by everyone.", ["par", "à", "avec"]], ["___ m'a volé mon portefeuille dans le métro.", "On", "", "My wallet was stolen in the metro.", ["Il", "J'", "Ils m'"]], ["Les billets ___ vendus en ligne uniquement.", "sont", "être", "Tickets are sold online only.", ["ont", "se sont", "étaient été"]], ["Ce vin se ___ avec du fromage.", "boit", "boire", "This wine is drunk with cheese.", ["bu", "boire", "buvait été"]]],
  fix: [["J'ai été offert un cadeau.", "J'ai été offert", "On m'a offert", "Offrir à quelqu'un is indirect: on m'a offert.", ["Je suis offerte", "Il m'a été offert par on"]], ["La maison a été vendu en mai.", "vendu", "vendue", "Agreement with la maison.", ["vendus", "vendre"]], ["Le projet sera présenté de la directrice.", "de", "par", "An action with an agent → par.", ["à", "avec"]]],
  xf: [["Make it passive.", "Le jury annoncera les résultats.", "Les résultats seront annoncés par le jury."], ["Rewrite with on.", "J'ai été informée du changement.", "On m'a informée du changement.|On m'a informé du changement."]],
  chat: [["Tu as eu des nouvelles de ta candidature ?", "Oui, on m'a proposé un entretien jeudi.", ["Oui, j'ai été proposée un entretien.", "Oui, un entretien m'a proposé."], "Proposer à quelqu'un: use on."], ["Le nouveau module est en ligne ?", "Pas encore, il sera publié lundi après validation.", ["Il sera publiée lundi.", "Il publiera lundi par nous."], "Passive future with agreement."]]
});

L({ id: "b2-participe", lvl: "B2", tr: "phrase2", cat: "syntaxe", t: "Participe présent et gérondif", en: "-ant forms: en travaillant, ayant fini",
  rule: { h: "Gérondif (en + -ant) refers to the subject of the sentence; the participe présent (-ant alone) describes a noun, mostly in writing.",
    pts: ["Form: nous-form minus <i>-ons</i> + <b>-ant</b>: <i>parlons → parlant, finissons → finissant</i>. Irregular: <i>étant, ayant, sachant</i>.", "<b>Gérondif</b> = same subject, two simultaneous actions, or the manner / the condition: <i>j'écoute des podcasts en cuisinant; c'est en forgeant qu'on devient forgeron</i>.", "<b>Participe présent</b> = replaces <i>qui</i> + verb, or gives a cause, in written style: <i>les candidats ayant réussi recevront un mail; étant malade, il n'est pas venu</i>.", "Compound form <b>ayant / étant + participle</b> for an earlier action: <i>ayant terminé mon travail, je suis sortie</i>.", "<i>Tout en</i> + gérondif adds opposition: <i>tout en étant fatiguée, elle a continué</i>."],
    ex: [["Je me suis cassé le bras en tombant.", "I broke my arm falling."], ["En partant maintenant, tu arriveras à l'heure.", "If you leave now, you'll arrive on time."], ["Les personnes souhaitant participer doivent s'inscrire.", "People wishing to take part must sign up."], ["Ayant raté le train, elle a pris un taxi.", "Having missed the train, she took a taxi."]],
    warn: "The gérondif must refer to the subject. <i>En arrivant, le chat m'a accueillie</i> means the cat arrived. Say: <i>quand je suis arrivée, le chat m'a accueillie</i>.",
    vn: "<b>vừa… vừa…</b> hoặc <b>bằng cách…</b> → gérondif: <i>Tôi nghe nhạc trong khi nấu ăn</i> = j'écoute de la musique <b>en cuisinant</b>. Chủ ngữ của hai hành động phải giống nhau." },
  cards: [["en + -ant", "while / by doing", "Elle chante en travaillant.", "She sings while working."], ["tout en", "while (with contrast)", "Tout en étant timide, il parle bien.", "Although shy, he speaks well."], ["étant", "being", "Étant fatiguée, je suis rentrée.", "Being tired, I went home."], ["ayant", "having", "Ayant fini, il est parti.", "Having finished, he left."], ["sachant que", "knowing that", "Sachant que tu aimes le thé, j'en ai acheté.", "Knowing you like tea, I bought some."], ["souhaitant", "wishing", "Les candidats souhaitant s'inscrire…", "Candidates wishing to register…"], ["en attendant", "while waiting, meanwhile", "En attendant, prends un café.", "Meanwhile, have a coffee."], ["c'est en… que", "it's by… that", "C'est en pratiquant qu'on progresse.", "It's by practising that you improve."]],
  sent: [["J'ai appris beaucoup de vocabulaire en regardant des séries.", "I learnt a lot of vocabulary watching series."], ["En prenant le métro, tu gagnes vingt minutes.", "By taking the metro, you save twenty minutes."], ["Il est entré en souriant.", "He came in smiling."], ["Les participants ayant un badge peuvent entrer.", "Participants with a badge may enter."], ["Ayant vécu à Saïgon, Alex comprend un peu le vietnamien.", "Having lived in Saigon, Alex understands a little Vietnamese."], ["Tout en aimant Paris, elle rêve parfois de la mer.", "While loving Paris, she sometimes dreams of the sea."], ["En arrivant au bureau, j'ai vu le message.", "When I got to the office, I saw the message."], ["Étant donné l'heure, nous devrions partir.", "Given the time, we should leave."], ["Sachant que le musée ferme tôt, nous y sommes allés le matin.", "Knowing the museum closes early, we went in the morning."], ["C'est en écrivant tous les jours qu'on progresse à l'écrit.", "It's by writing every day that you improve in writing."]],
  nat: [["Quand je suis arrivée, le chat dormait.", "En arrivant, le chat dormait.", "The gérondif must share the subject of the sentence: here it would mean the cat was arriving."], ["Ayant fini mon travail, je suis partie.", "Ayant finie mon travail, je suis partie.", "Ayant + participle: no agreement here."], ["En lisant, on apprend.", "En lisons, on apprend.", "Gérondif: en + -ant."], ["Sachant cela, j'ai accepté.", "Savant cela, j'ai accepté.", "Savoir → sachant."]],
  mcq: [["Il s'est blessé ___ du ski.", "en faisant", ["faisant en", "à faire", "en fait"], "Gérondif: en faisant."], ["___ malade, elle n'est pas venue.", "Étant", ["En étant", "Été", "Être"], "Cause in written style: participe présent."], ["Les étudiants ___ le cours peuvent s'inscrire à l'examen.", "ayant suivi", ["en suivant", "suivant ayant", "ayant suivis"], "Compound participle replacing qui ont suivi."], ["On apprend à nager ___.", "en nageant", ["nageant en", "à nager en", "en nager"], "Manner: gérondif."]],
  gap: [["Elle écoute la radio ___ le petit-déjeuner.", "en préparant", "préparer", "She listens to the radio while making breakfast.", ["préparant", "en préparer", "en préparé"]], ["___ un peu de temps libre, elle est passée nous voir.", "Ayant", "avoir", "Having a little free time, she dropped by to see us.", ["Étant", "En ayant eu", "Eu"]], ["___ que tu étais occupée, je ne t'ai pas appelée.", "Sachant", "savoir", "Knowing you were busy, I didn't call you.", ["Savant", "En sachant", "Su"]], ["Il est parti ___ au revoir.", "sans dire", "dire", "He left without saying goodbye.", ["en ne disant pas", "sans disant", "sans dit"]], ["C'est en ___ qu'on devient forgeron.", "forgeant", "forger", "Practice makes perfect.", ["forgeons", "forgé", "forger"]], ["___ terminé ses études, elle est rentrée au Viêt Nam.", "Ayant", "avoir", "Having finished her studies, she went back to Vietnam.", ["Étant", "En ayant", "Avant"]]],
  fix: [["En arrivant à la gare, le train était déjà parti.", "En arrivant à la gare", "Quand je suis arrivée à la gare", "The gérondif would refer to le train. Use a clause.", ["En arrivant le train", "Arrivant"]], ["Il travaille en écoutant de la musique et en chante.", "en chante", "en chantant", "Gérondif: en + -ant.", ["chantant", "en chanter"]], ["Savant la vérité, il n'a rien dit.", "Savant", "Sachant", "Savoir → sachant.", ["Saviez", "Sachez"]]],
  xf: [["Use a gérondif.", "Pendant que je cuisine, j'écoute des podcasts.", "J'écoute des podcasts en cuisinant."], ["Use ayant + participle.", "Comme elle avait réussi l'examen, elle a fêté ça.", "Ayant réussi l'examen, elle a fêté ça."]],
  chat: [["Comment tu as appris le français si vite ?", "En lisant beaucoup et en parlant avec la famille d'Alex.", ["En lisons beaucoup.", "Lisant beaucoup en parlant."], "Manner: gérondif."], ["Tu as trouvé le bureau facilement ?", "Oui, en suivant le plan que tu m'as envoyé.", ["Oui, suivant en le plan.", "Oui, en suit le plan."], "Gérondif: en suivant."]]
});

L({ id: "b2-relief", lvl: "B2", tr: "phrase2", cat: "syntaxe", t: "La mise en relief", en: "C'est… qui / que, ce qui… c'est",
  rule: { h: "To highlight an element, French moves it into a frame: c'est… qui/que, or ce qui / ce que… c'est.",
    pts: ["Subject: <i><b>C'est</b> Alex <b>qui</b> a choisi le restaurant</i>.", "Other elements: <i><b>C'est</b> à Saïgon <b>que</b> nous nous sommes mariés</i>.", "<b>Ce qui</b> (subject) / <b>ce que</b> (object) / <b>ce dont</b> (de)… <b>c'est</b>: <i>ce que j'aime, c'est la lumière de Paris</i>.", "Dislocation in speech: <i>Paris, je l'adore. Moi, je trouve que…</i>", "With a person pronoun: <i>c'est moi qui ai raison</i> — the verb agrees with moi."],
    ex: [["C'est elle qui m'a appris à cuisiner.", "She's the one who taught me to cook."], ["C'est en 2022 que nous nous sommes rencontrés.", "It was in 2022 that we met."], ["Ce qui me manque, c'est le soleil.", "What I miss is the sun."], ["Ce dont j'ai besoin, c'est d'un peu de repos.", "What I need is a little rest."]],
    warn: "<i>C'est moi qui <b>ai</b> raison, c'est nous qui <b>avons</b> décidé</i>: the verb agrees with the pronoun, not with il.",
    vn: "Giống <b>«Chính… là người…»</b> hoặc <b>«Điều tôi… là…»</b>: <i>C'est Alex qui a choisi</i> = Chính Alex là người chọn. <i>Ce qui me manque, c'est…</i> = Điều tôi nhớ là…" },
  cards: [["c'est… qui", "it's… who/that (subject)", "C'est ma mère qui a fait ce gâteau.", "My mother is the one who made this cake."], ["c'est… que", "it's… that (other)", "C'est demain que tout se décide.", "It's tomorrow that everything is decided."], ["ce qui… c'est", "what… is (subject)", "Ce qui compte, c'est la santé.", "What matters is health."], ["ce que… c'est", "what… is (object)", "Ce que je préfère, c'est le printemps.", "What I prefer is spring."], ["ce dont… c'est", "what… is (de)", "Ce dont je rêve, c'est d'un jardin.", "What I dream of is a garden."], ["ce à quoi", "what (à)", "Ce à quoi je pense, c'est l'avenir.", "What I'm thinking about is the future."], ["moi, je", "as for me", "Moi, je préfère la mer.", "Me, I prefer the sea."], ["voilà pourquoi", "that's why", "Voilà pourquoi j'ai refusé.", "That's why I refused."]],
  sent: [["C'est Alex qui a fait la demande en mariage, à Hội An.", "Alex is the one who proposed, in Hội An."], ["C'est à Paris que j'ai découvert le fromage.", "It was in Paris that I discovered cheese."], ["Ce qui m'a surprise, c'est la gentillesse des gens.", "What surprised me was how kind people were."], ["Ce que je cherche, c'est un poste plus stratégique.", "What I'm looking for is a more strategic role."], ["Ce dont nous avons besoin, c'est d'une salle plus grande.", "What we need is a bigger room."], ["C'est nous qui organisons la fête cette année.", "We're the ones organising the party this year."], ["C'est pour toi que j'ai acheté ces fleurs.", "It's for you that I bought these flowers."], ["Le bruit, je ne le supporte plus.", "The noise, I can't stand it any more."], ["C'est en pratiquant chaque jour que j'ai progressé.", "It's by practising every day that I improved."], ["Ce à quoi je ne m'attendais pas, c'est la neige en avril.", "What I didn't expect was snow in April."]],
  nat: [["C'est moi qui ai raison.", "C'est moi qui a raison.", "Agreement with moi: ai."], ["Ce qui me plaît, c'est le calme.", "Ce que me plaît, c'est le calme.", "Subject of plaît → ce qui."], ["Ce dont j'ai envie, c'est d'un voyage.", "Ce que j'ai envie, c'est un voyage.", "Avoir envie de → ce dont… c'est de."], ["C'est en mai que nous partons.", "C'est en mai qui nous partons.", "A time complement → que."]],
  mcq: [["___ m'inquiète, c'est le prix.", "Ce qui", ["Ce que", "Ce dont", "Qui"], "Subject of inquiète."], ["C'est vous qui ___ choisi ?", "avez", ["a", "ont", "avons"], "Agreement with vous."], ["___ j'ai peur, c'est de l'échec.", "Ce dont", ["Ce que", "Ce qui", "Dont"], "Avoir peur de → ce dont."], ["C'est grâce à toi ___ j'ai réussi.", "que", ["qui", "dont", "où"], "A complement → c'est… que."]],
  gap: [["C'est ma sœur ___ m'a présenté Alex.", "qui", "", "My sister is the one who introduced me to Alex.", ["que", "dont", "ce qui"]], ["___ j'adore à Paris, ce sont les marchés.", "Ce que", "", "What I love in Paris are the markets.", ["Ce qui", "Ce dont", "Qu'"]], ["C'est toi qui ___ le dernier mot.", "as", "avoir", "You have the last word.", ["a", "ai", "avez"]], ["___ me fait rire, c'est son accent.", "Ce qui", "", "What makes me laugh is his accent.", ["Ce que", "Ce dont", "Qui"]], ["C'est en Bretagne ___ nous passons l'été.", "que", "", "It's in Brittany that we spend the summer.", ["qui", "où", "dont"]], ["___ je me souviens, c'est de son sourire.", "Ce dont", "", "What I remember is her smile.", ["Ce que", "Ce qui", "Dont"]]],
  fix: [["C'est nous qui a gagné.", "a gagné", "avons gagné", "Agreement with nous.", ["ont gagné", "ai gagné"]], ["Ce que me dérange, c'est le bruit.", "Ce que", "Ce qui", "Subject of dérange → ce qui.", ["Ce dont", "Qui"]], ["Ce que j'ai besoin, c'est de dormir.", "Ce que", "Ce dont", "Avoir besoin de → ce dont.", ["Ce qui", "Ce à quoi"]]],
  xf: [["Highlight the subject.", "Lan Anh a trouvé la salle.", "C'est Lan Anh qui a trouvé la salle."], ["Begin with Ce que… c'est.", "J'aime surtout la lumière du matin.", "Ce que j'aime surtout, c'est la lumière du matin.|Ce que j'aime, c'est la lumière du matin."]],
  chat: [["Qu'est-ce qui te plaît le plus dans ton travail ?", "Ce qui me plaît le plus, c'est de concevoir des parcours de formation.", ["Ce que me plaît le plus…", "Qui me plaît, c'est concevoir."], "Subject of plaît → ce qui."], ["C'est qui qui a choisi ce restaurant ?", "C'est moi qui l'ai choisi, il te plaît ?", ["C'est moi qui l'a choisi.", "C'est moi que l'ai choisi."], "C'est moi qui ai."]]
});

L({ id: "b2-demonstr", lvl: "B2", tr: "phrase2", cat: "pronoms", t: "Celui, le mien", en: "Demonstrative and possessive pronouns",
  rule: { h: "Celui / celle / ceux / celles replace a noun already mentioned; le mien / la tienne… replace a possessive + noun.",
    pts: ["<b>Celui-ci / celui-là</b> to choose: <i>quelle robe ? — celle-ci</i>.", "<b>Celui qui / que / dont / où</b>: <i>celui que je préfère, ceux dont je t'ai parlé</i>.", "<b>Celui de</b> for possession: <i>mon téléphone et celui d'Alex</i>.", "Possessives: <i>le mien, la mienne, les miens, les miennes; le tien…; le sien…; le nôtre, la nôtre, les nôtres; le vôtre…; le leur, la leur, les leurs</i>.", "With à and de: <i>je pense au tien, je parle du sien</i>."],
    ex: [["Quel gâteau tu veux ? — Celui au chocolat.", "Which cake do you want? — The chocolate one."], ["Ceux qui veulent venir sont les bienvenus.", "Those who want to come are welcome."], ["Mon vélo est cassé ; je peux prendre le tien ?", "My bike is broken; can I take yours?"], ["Leur appartement est plus grand que le nôtre.", "Their flat is bigger than ours."]],
    warn: "<i>Le nôtre, le vôtre</i> take a circumflex; <i>notre, votre</i> (adjectives) do not.",
    vn: "<b>cái này / cái kia</b> → celui-ci / celui-là; <b>của tôi</b> → le mien / la mienne. Tiếng Pháp phải chọn giống và số theo <b>danh từ được thay thế</b>, không theo người sở hữu: <i>la sienne</i> có thể là «của anh ấy»." },
  cards: [["celui-ci", "this one", "Je prends celui-ci.", "I'll take this one."], ["celle-là", "that one (fem.)", "Pas cette robe, celle-là.", "Not this dress, that one."], ["ceux qui", "those who", "Ceux qui ont fini peuvent partir.", "Those who've finished can leave."], ["celui de", "the one of / …'s", "Ce sac, c'est celui de ma mère.", "This bag is my mother's."], ["le mien", "mine (masc.)", "Ton café est froid ? Le mien aussi.", "Your coffee is cold? Mine too."], ["la tienne", "yours (fem., tu)", "Ma valise est rouge, et la tienne ?", "My suitcase is red, and yours?"], ["le nôtre", "ours", "Votre jardin est plus grand que le nôtre.", "Your garden is bigger than ours."], ["les leurs", "theirs (plural)", "Nos enfants jouent avec les leurs.", "Our children play with theirs."]],
  sent: [["Entre les deux appartements, je préfère celui qui a un balcon.", "Of the two flats, I prefer the one with a balcony."], ["Mes parents habitent à Đà Lạt, ceux d'Alex à Bordeaux.", "My parents live in Đà Lạt, Alex's in Bordeaux."], ["Ce n'est pas ton parapluie, c'est le mien.", "It's not your umbrella, it's mine."], ["Ceux qui arrivent en retard attendront dehors.", "Those who arrive late will wait outside."], ["Ta proposition est meilleure que la mienne.", "Your proposal is better than mine."], ["Parmi tous les cafés du quartier, celui-ci est mon préféré.", "Of all the cafés in the area, this one is my favourite."], ["Nos invités et les leurs seront à la même table.", "Our guests and theirs will be at the same table."], ["J'ai oublié mon chargeur ; tu peux me prêter le tien ?", "I forgot my charger; can you lend me yours?"], ["Celle dont je t'ai parlé travaille à l'OCDE.", "The woman I told you about works at the OECD."], ["Mon dossier est complet ; et le vôtre, madame ?", "My file is complete; what about yours, madam?"]],
  nat: [["Ma voiture est grise, la tienne est bleue.", "Ma voiture est grise, le tien est bleu.", "Voiture is feminine → la tienne."], ["Celui que je préfère, c'est le rouge.", "Celui qui je préfère, c'est le rouge.", "Object → celui que."], ["Notre maison est petite, la vôtre est grande.", "Notre maison est petite, la votre est grande.", "La vôtre takes a circumflex."], ["Ce livre, c'est celui de Marie.", "Ce livre, c'est le de Marie.", "Possession → celui de."]],
  mcq: [["Mes clés sont ici. Où sont ___ ?", "les tiennes", ["les tiens", "la tienne", "le tien"], "Clés is feminine plural."], ["Quelle chemise ? ___ que j'ai achetée hier.", "Celle", ["Celui", "Ceux", "Cette"], "Chemise is feminine."], ["Leurs enfants sont plus âgés que ___.", "les nôtres", ["les notres", "nos", "la nôtre"], "Plural, with circumflex."], ["___ qui ont réservé peuvent entrer.", "Ceux", ["Celui", "Ces", "Les uns"], "Plural people."]],
  gap: [["Ton idée est meilleure que la ___.", "mienne", "", "Your idea is better than mine.", ["mien", "miennes", "mon"]], ["Ces chaussures sont jolies, mais je préfère ___-là.", "celles", "", "These shoes are nice, but I prefer those.", ["ceux", "celle", "ces"]], ["Mon train part à 8 h ; ___ de Claire à 9 h.", "celui", "", "My train leaves at 8; Claire's at 9.", ["celle", "le sien", "ce"]], ["Notre mariage sera en janvier ; le ___ en juin ?", "vôtre", "", "Our wedding will be in January; yours in June?", ["votre", "vôtres", "vous"]], ["Elle a perdu son badge ; je lui ai prêté le ___.", "mien", "", "She lost her badge; I lent her mine.", ["mienne", "mon", "miens"]], ["___ dont tu parles n'existe plus.", "Celui|Celle", "", "The one you're talking about no longer exists.", ["Ce", "Lequel", "Cela"]]],
  fix: [["Ma valise est lourde, mais le tien est plus lourde.", "le tien", "la tienne", "Valise is feminine.", ["les tiens", "ton"]], ["Notre maison est plus petite que la votre.", "la votre", "la vôtre", "Pronoun → vôtre with a circumflex.", ["la vôtres", "votre"]], ["Ceux qui je connais sont gentils.", "Ceux qui", "Ceux que", "Object of connais → que.", ["Ceux dont", "Ceux où"]]],
  xf: [["Avoid repeating the noun.", "Mon ordinateur est lent. Ton ordinateur est rapide.", "Mon ordinateur est lent, le tien est rapide.|Mon ordinateur est lent. Le tien est rapide."], ["Avoid repeating the noun.", "Les gens qui sont venus étaient contents.", "Ceux qui sont venus étaient contents."]],
  chat: [["C'est ton écharpe, celle-ci ?", "Non, la mienne est bleue ; celle-ci doit être celle de Claire.", ["Non, le mien est bleu.", "Non, la mien est bleue."], "Écharpe is feminine."], ["Vos parents viennent au mariage ?", "Oui, les miens et ceux d'Alex seront là.", ["Oui, les miennes et celles d'Alex.", "Oui, mes et les d'Alex."], "Parents is masculine plural: les miens, ceux de."]]
});
